"""Restricted stdlib verifier for XLSX files generated by M10-D.

This is deliberately not a general spreadsheet reader and has no import path
back into the machine ledger.  It accepts only the small OOXML subset emitted
by the pinned audit-copy writer and compares every cell with verified CSV rows.
"""

from __future__ import annotations

from dataclasses import dataclass
from decimal import Decimal, InvalidOperation
from pathlib import Path, PurePosixPath
import posixpath
import re
from typing import Any, Mapping, Sequence
from xml.etree import ElementTree as ET
import zipfile

from services.contracts.validation import ContractError


_MAIN = "http://schemas.openxmlformats.org/spreadsheetml/2006/main"
_OFFICE_REL = "http://schemas.openxmlformats.org/officeDocument/2006/relationships"
_PACKAGE_REL = "http://schemas.openxmlformats.org/package/2006/relationships"
_R_ID = f"{{{_OFFICE_REL}}}id"
_CELL_REF = re.compile(r"^([A-Z]+)([1-9][0-9]*)$")
_WORKSHEET = re.compile(r"^xl/worksheets/sheet[1-9][0-9]*\.xml$")
_FIXED_MEMBERS = {
    "[Content_Types].xml",
    "_rels/.rels",
    "docProps/app.xml",
    "docProps/core.xml",
    "xl/_rels/workbook.xml.rels",
    "xl/styles.xml",
    "xl/theme/theme1.xml",
    "xl/workbook.xml",
}


@dataclass(frozen=True)
class _Cell:
    kind: str
    value: str | Decimal | bool


def _local(tag: str) -> str:
    return tag.rsplit("}", 1)[-1]


def _safe_member(name: str) -> None:
    if "\\" in name or name.startswith("/"):
        raise ContractError("M10-D XLSX ZIP member path is unsafe")
    parts = name.split("/")
    if any(part in {"", ".", ".."} for part in parts):
        raise ContractError("M10-D XLSX ZIP member path is unsafe")
    if PurePosixPath(name).as_posix() != name:
        raise ContractError("M10-D XLSX ZIP member path is not canonical")


def _read_xml(archive: zipfile.ZipFile, name: str) -> ET.Element:
    try:
        raw = archive.read(name)
    except (KeyError, OSError, RuntimeError) as exc:
        raise ContractError("M10-D XLSX required XML part is unreadable") from exc
    if b"<!DOCTYPE" in raw.upper() or b"<!ENTITY" in raw.upper():
        raise ContractError("M10-D XLSX XML declarations are not allowed")
    try:
        return ET.fromstring(raw)
    except ET.ParseError as exc:
        raise ContractError("M10-D XLSX XML is malformed") from exc


def _column_number(letters: str) -> int:
    value = 0
    for letter in letters:
        value = value * 26 + ord(letter) - ord("A") + 1
    return value


def _column_letters(number: int) -> str:
    letters = ""
    while number:
        number, remainder = divmod(number - 1, 26)
        letters = chr(ord("A") + remainder) + letters
    return letters


def _cell_value(cell: ET.Element) -> _Cell:
    if any(_local(item.tag) == "f" for item in cell.iter()):
        raise ContractError("M10-D XLSX cannot contain formulas")
    cell_type = cell.get("t")
    children = list(cell)
    if cell_type == "inlineStr":
        if len(children) != 1 or _local(children[0].tag) != "is":
            raise ContractError("M10-D XLSX inline string is malformed")
        string_children = list(children[0])
        if len(string_children) != 1 or _local(string_children[0].tag) != "t":
            raise ContractError("M10-D XLSX rich or malformed text is not allowed")
        return _Cell("text", string_children[0].text or "")
    if cell_type == "b":
        if len(children) != 1 or _local(children[0].tag) != "v":
            raise ContractError("M10-D XLSX boolean is malformed")
        if children[0].text not in {"0", "1"}:
            raise ContractError("M10-D XLSX boolean value is invalid")
        return _Cell("bool", children[0].text == "1")
    if cell_type not in {None, "n"}:
        raise ContractError("M10-D XLSX cell type is outside the approved subset")
    if len(children) != 1 or _local(children[0].tag) != "v":
        raise ContractError("M10-D XLSX numeric cell is malformed")
    try:
        number = Decimal(children[0].text or "")
    except (InvalidOperation, ValueError) as exc:
        raise ContractError("M10-D XLSX number is invalid") from exc
    if not number.is_finite():
        raise ContractError("M10-D XLSX number must be finite")
    return _Cell("number", number)


def _expected_cell(spec: Any, value: Any) -> _Cell:
    from .export import encode_audit_cell

    if value is None:
        return _Cell("text", r"\N")
    if spec.kind == "bool":
        if not isinstance(value, bool):
            raise ContractError("M10-D expected boolean has the wrong type")
        return _Cell("bool", value)
    if spec.kind == "int":
        if isinstance(value, bool) or not isinstance(value, int):
            raise ContractError("M10-D expected integer has the wrong type")
        return _Cell("number", Decimal(value))
    if spec.kind == "decimal":
        if not isinstance(value, Decimal) or not value.is_finite():
            raise ContractError("M10-D expected Decimal has the wrong type")
        return _Cell("number", value)
    return _Cell("text", encode_audit_cell(value, spec.kind))


def _verify_worksheet(
    archive: zipfile.ZipFile,
    member: str,
    artifact: Mapping[str, Any],
    expected_rows: Sequence[Mapping[str, Any]],
) -> None:
    from .export import DATASET_COLUMNS

    columns = DATASET_COLUMNS[str(artifact["dataset"])]
    expected_row_number = 1
    saw_pane = False
    auto_filter: str | None = None
    dimension: str | None = None
    try:
        with archive.open(member, "r") as prefix_handle:
            prefix = prefix_handle.read(2048)
        if (
            b"<!DOCTYPE" in prefix.upper()
            or b"<!ENTITY" in prefix.upper()
            or b"<worksheet" not in prefix
        ):
            raise ContractError("M10-D XLSX worksheet prolog is invalid")
        with archive.open(member, "r") as handle:
            root_seen = False
            for event, element in ET.iterparse(handle, events=("start", "end")):
                if not root_seen and event == "start":
                    if element.tag != f"{{{_MAIN}}}worksheet":
                        raise ContractError("M10-D XLSX worksheet root is invalid")
                    root_seen = True
                if event != "end":
                    continue
                local = _local(element.tag)
                if local in {"f", "hyperlink", "hyperlinks"}:
                    raise ContractError("M10-D XLSX formulas or hyperlinks are not allowed")
                if local == "pane":
                    saw_pane = (
                        element.get("state") == "frozen"
                        and element.get("ySplit") == "1"
                        and element.get("topLeftCell") == "A2"
                    )
                elif local == "autoFilter":
                    auto_filter = element.get("ref")
                elif local == "dimension":
                    dimension = element.get("ref")
                elif local == "row":
                    row_text = element.get("r")
                    if row_text != str(expected_row_number):
                        raise ContractError("M10-D XLSX rows are not contiguous")
                    cells = [item for item in list(element) if _local(item.tag) == "c"]
                    if len(cells) != len(columns) or len(cells) != len(list(element)):
                        raise ContractError("M10-D XLSX row is not rectangular")
                    values: list[_Cell] = []
                    for column_number, cell in enumerate(cells, 1):
                        reference = cell.get("r")
                        match = _CELL_REF.fullmatch(reference or "")
                        if (
                            match is None
                            or _column_number(match.group(1)) != column_number
                            or int(match.group(2)) != expected_row_number
                        ):
                            raise ContractError("M10-D XLSX cell address is invalid")
                        values.append(_cell_value(cell))
                    if expected_row_number == 1:
                        expected = [_Cell("text", item.name) for item in columns]
                    else:
                        data_index = expected_row_number - 2
                        if data_index >= len(expected_rows):
                            raise ContractError("M10-D XLSX contains extra data rows")
                        source = expected_rows[data_index]
                        expected = [
                            _expected_cell(spec, source[spec.name]) for spec in columns
                        ]
                    if values != expected:
                        raise ContractError("M10-D XLSX cell differs from its CSV authority")
                    expected_row_number += 1
                    element.clear()
    except (ET.ParseError, OSError, RuntimeError) as exc:
        if isinstance(exc, ContractError):
            raise
        raise ContractError("M10-D XLSX worksheet is unreadable") from exc
    expected_last_row = len(expected_rows) + 1
    if expected_row_number != expected_last_row + 1:
        raise ContractError("M10-D XLSX worksheet row count is incomplete")
    expected_range = f"A1:{_column_letters(len(columns))}{expected_last_row}"
    if dimension != expected_range or auto_filter != expected_range:
        raise ContractError("M10-D XLSX worksheet range is inconsistent")
    if not saw_pane:
        raise ContractError("M10-D XLSX first row is not frozen")


def verify_generated_audit_workbook(
    path: Path,
    *,
    worksheet_artifacts: Sequence[Mapping[str, Any]],
    csv_parts: Mapping[tuple[str, int], Sequence[Mapping[str, Any]]],
) -> None:
    """Verify the generated OOXML subset and every cell against CSV parts."""

    expected_names = [str(item["worksheet_name"]) for item in worksheet_artifacts]
    if len(expected_names) != len(set(expected_names)):
        raise ContractError("M10-D XLSX expected worksheet names are duplicated")
    try:
        with zipfile.ZipFile(path, "r") as archive:
            infos = archive.infolist()
            names = [item.filename for item in infos]
            if len(names) != len(set(names)):
                raise ContractError("M10-D XLSX contains duplicate ZIP members")
            for info in infos:
                _safe_member(info.filename)
                if info.flag_bits & 0x1:
                    raise ContractError("M10-D XLSX cannot contain encrypted members")
                if info.date_time != (1980, 1, 1, 0, 0, 0):
                    raise ContractError("M10-D XLSX ZIP metadata is not deterministic")
            worksheet_members = {name for name in names if _WORKSHEET.fullmatch(name)}
            if set(names) != _FIXED_MEMBERS | worksheet_members:
                raise ContractError("M10-D XLSX contains an unsupported OOXML part")
            if archive.testzip() is not None:
                raise ContractError("M10-D XLSX ZIP integrity check failed")
            for relationship_name in ("_rels/.rels", "xl/_rels/workbook.xml.rels"):
                relationships = _read_xml(archive, relationship_name)
                for relationship in relationships:
                    if relationship.get("TargetMode") == "External":
                        raise ContractError("M10-D XLSX external relationships are forbidden")

            workbook = _read_xml(archive, "xl/workbook.xml")
            file_sharing = workbook.find(f"{{{_MAIN}}}fileSharing")
            if file_sharing is None or file_sharing.get("readOnlyRecommended") != "1":
                raise ContractError("M10-D XLSX must be marked read-only recommended")
            sheets = workbook.find(f"{{{_MAIN}}}sheets")
            if sheets is None:
                raise ContractError("M10-D XLSX workbook has no sheets")
            sheet_items = list(sheets)
            actual_names = [item.get("name") for item in sheet_items]
            if actual_names != expected_names:
                raise ContractError("M10-D XLSX worksheet names or order are invalid")
            if any(item.get("state") not in {None, "visible"} for item in sheet_items):
                raise ContractError("M10-D XLSX worksheets cannot be hidden")

            relationships = _read_xml(archive, "xl/_rels/workbook.xml.rels")
            relation_map: dict[str, str] = {}
            for relationship in relationships.findall(f"{{{_PACKAGE_REL}}}Relationship"):
                if relationship.get("TargetMode") == "External":
                    raise ContractError("M10-D XLSX external relationships are forbidden")
                relation_id = relationship.get("Id")
                target = relationship.get("Target")
                if not relation_id or not target:
                    raise ContractError("M10-D XLSX relationship is incomplete")
                resolved = posixpath.normpath(posixpath.join("xl", target))
                if resolved.startswith("../") or resolved.startswith("/"):
                    raise ContractError("M10-D XLSX relationship target is unsafe")
                relation_map[relation_id] = resolved
            actual_members: list[str] = []
            for sheet in sheet_items:
                relation_id = sheet.get(_R_ID)
                member = relation_map.get(relation_id or "")
                if member is None or member not in worksheet_members:
                    raise ContractError("M10-D XLSX worksheet relationship is invalid")
                actual_members.append(member)
            if len(actual_members) != len(set(actual_members)) or set(actual_members) != worksheet_members:
                raise ContractError("M10-D XLSX worksheet relationships are not one-to-one")

            for artifact, member in zip(worksheet_artifacts, actual_members, strict=True):
                key = (str(artifact["dataset"]), int(artifact["part_number"]))
                if key not in csv_parts:
                    raise ContractError("M10-D XLSX worksheet lacks its CSV part")
                _verify_worksheet(archive, member, artifact, csv_parts[key])
    except (OSError, zipfile.BadZipFile, RuntimeError) as exc:
        if isinstance(exc, ContractError):
            raise
        raise ContractError("M10-D XLSX package is unreadable") from exc


__all__: list[str] = []
